static long Fib(int n)
{
    if (n <= 1) return n;
    return Fib(n - 1) + Fib(n - 2);
}

var memo = new Dictionary<int, long>();
long FibM(int n)
{
    if (n <= 1) return n;
    if (memo.TryGetValue(n, out long w))
        return w;
    long e = FibM(n - 1) + FibM(n - 2);
    memo[n] = e;
    return e;
}

Console.WriteLine(Fib(10));
Console.WriteLine(FibM(90));
// Ausgabe:
// 55
// 2880067194370816120

static long Potenz(long x, int n)
{
    if (n == 0) return 1;
    if (n % 2 == 1)
        return x * Potenz(x, n - 1);
    long h = Potenz(x, n / 2);
    return h * h;
}

Console.WriteLine(Potenz(2, 10));
Console.WriteLine(Potenz(3, 13));
// Ausgabe:
// 1024
// 1594323

static int Suche(int[] a, int ziel,
                 int von, int bis)
{
    if (von > bis) return -1;
    int m = (von + bis) / 2;
    if (a[m] == ziel) return m;
    if (ziel < a[m])
        return Suche(a, ziel, von, m - 1);
    return Suche(a, ziel, m + 1, bis);
}

int[] w = { 3, 8, 12, 17, 21, 30, 42 };
Console.WriteLine(Suche(w, 21, 0, 6));
Console.WriteLine(Suche(w, 5, 0, 6));
// Ausgabe:
// 4
// -1

static void Hanoi(int n, char von,
                  char ziel, char hilf)
{
    if (n == 0) return;
    Hanoi(n - 1, von, hilf, ziel);
    Console.WriteLine(
        $"{n}: {von} -> {ziel}");
    Hanoi(n - 1, hilf, ziel, von);
}

Hanoi(2, 'A', 'C', 'B');
// Ausgabe:
// 1: A -> B
// 2: A -> C
// 1: B -> C
